"""`.KK Eyebrows`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.KK Eyebrows'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Light colors', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('OUTPUT', 'Dark colors', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('INPUT', 'Eyebrow color', 'NodeSocketColor', default_value=(0.65934676, 0.7603235, 0.7603235, 1.0))
    t.socket('INPUT', 'Eyebrow color dark', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('INPUT', 'Use main texture color?', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Main texture', 'NodeSocketColor', default_value=(0.5, 0.5, 0.5, 1.0))

    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (190.0, 0.0),
    })
    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-200.0, 0.0),
    })
    t.node('ShaderNodeMix', 'Mix', inputs={'Factor_Float': 0.0, 'A_Color': (0.65934676, 0.7603235, 0.7603235, 1.0)}, props={
        'data_type': 'RGBA',
        'blend_type': 'MULTIPLY',
        'location': (0.0, 0.0),
    })
    t.node('ShaderNodeMix', 'Mix dark', props={
        'location': (0.0, -220.0),
        'data_type': 'RGBA',
        'blend_type': 'MULTIPLY',
    })

    t.link('Group Input', 'Main texture', 'Mix', 'B_Color')
    t.link('Mix', 'Result_Color', 'Group Output', 'Light colors')
    t.link('Group Input', 'Use main texture color?', 'Mix', 'Factor_Float')
    t.link('Group Input', 'Eyebrow color', 'Mix', 'A_Color')
    t.link('Group Input', 'Use main texture color?', 'Mix dark', 'Factor_Float')
    t.link('Group Input', 'Eyebrow color dark', 'Mix dark', 'A_Color')
    t.link('Group Input', 'Main texture', 'Mix dark', 'B_Color')
    t.link('Mix dark', 'Result_Color', 'Group Output', 'Dark colors')
    return t
